(2957346, 411338, 51538, '<td valign="top">Very funny and nicely composed too. 9.</td>', 'Very funny and nicely composed too. 9.', '2006-10-24 11:49:30.000000', NULL, 1),
(2957347, 413203, 51538, '<td valign="top">Perfectly apt for the saying. 8.</td>', 'Perfectly apt for the saying. 8.', '2006-10-24 11:49:53.000000', NULL, 1),
