INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2960730, 413155, 52549, '<td valign="top">Great shot Enzo. Freezing the action with sugar is something I haven''t tried yet....;-) It worked out very well for you though and the idea, colours and composition are wonderful. Congratulations on your top 10 finish.</td>', 'Great shot Enzo. Freezing the action with sugar is something I haven''t tried yet....;-) It worked out very well for you though and the idea, colours and composition are wonderful. Congratulations on your top 10 finish.', '2006-10-25 10:06:01.000000', NULL, 0),
(2960771, 412139, 65899, '<td valign="top">Nice rotation. Love the picture!<br/> <br/>If you want this to be more convincing, remember that:<br/> <br/>a) nobody builds a concrete wall witha verticle seam unless they want that concrete wall to fall down.<br/> <br/>b) on Earth, rust stains would follow the line of gravity, which is generally downwards.<br/> <br/>:-)<br/>Sarcasm aside, and it''s meant to be humourous, if you did a re-shoot of that in a different location bearing in mind the ''giveways'' it would be fantastic. Nice one!</td>', 'Nice rotation. Love the picture! If you want this to be more convincing, remember that: a) nobody builds a concrete wall witha verticle seam unless they want that concrete wall to fall down. b) on Earth, rust stains would follow the line of gravity, which is generally downwards. :-)Sarcasm aside, and it''s meant to be humourous, if you did a re-shoot of that in a different location bearing in mind the ''giveways'' it would be fantastic. Nice one!', '2006-10-25 10:17:29.000000', NULL, 0),
(2960845, 413002, 31399, '<td valign="top">sorry I didn''t vote this one.  I''d have given you and 8.  I REALLY like the way the fork reflection looks like it''s a spoon.  Your really doing a nice job with shots!  Keep up the good work!</td>', 'sorry I didn''t vote this one.  I''d have given you and 8.  I REALLY like the way the fork reflection looks like it''s a spoon.  Your really doing a nice job with shots!  Keep up the good work!', '2006-10-25 10:30:48.000000', NULL, 0),
(2960895, 412706, 33392, '<td valign="top">I know this is a rant, but how in the world could anybody give this a 1,2, or a 3?  The twelve 4''s mystify me, but I can live with that.<br/> <br/>Your imagination and creativity never ceases to amaze me.  Keep up the great work.</td>', 'I know this is a rant, but how in the world could anybody give this a 1,2, or a 3?  The twelve 4''s mystify me, but I can live with that. Your imagination and creativity never ceases to amaze me.  Keep up the great work.', '2006-10-25 10:45:45.000000', NULL, 0),
